const nodes = [{"id":"start","name":"中央苏区","date":"1934.10","title":"战略转移，从中央苏区出发","text":"1934 年 10 月，中共中央和中央红军主力撤离中央革命根据地，开始长征。","source":"《多视角下看长征》·共产党员网","url":"https://www.12371.cn/2021/10/19/ARTI1634643519286309.shtml","x":84,"y":79,"questions":["中央红军什么时候开始长征？","各路红军都从这里出发吗？"],"extra":[{"id":"start_scope","text":"中央红军主力于 1934 年 10 月开始战略转移。红二十五军、红四方面军和红二、红六军团后来分别从不同根据地出发，时间和路线并不相同。","source":"《多视角下看长征》·共产党员网","url":"https://www.12371.cn/2021/10/19/ARTI1634643519286309.shtml"},{"id":"start_yudu","text":"1934 年 10 月 10 日，中共中央、中革军委率第 1、第 2 野战纵队从江西瑞金等地出发；17 日起，中央红军主力从于都河等渡口渡河，开始战略转移。","source":"《中央红军战略转移序章——突破三道封锁线》·人民网","url":"https://cpc.people.com.cn/n1/2026/1114/c443712-40833771.html"}]},{"id":"xiangjiang","name":"湘江","date":"1934.11—12","title":"突破封锁，付出重大代价","text":"1934 年 11 月 27 日至 12 月 1 日，中央红军进行湘江之战，突破敌军封锁，部队付出重大代价。","source":"《遵义会议：中国共产党历史的伟大转折》·共产党员网","url":"https://www.12371.cn/2021/08/12/ARTI1628761880703772.shtml","x":73,"y":71,"questions":["湘江之战发生在什么时候？","湘江之战付出了什么代价？"],"extra":[{"id":"xiangjiang_detail","text":"中央红军长征初期原计划向湘西北转移，与红二、红六军团会合；湘江之战中，红军突破敌军第四道封锁线，损失惨重。","source":"《遵义会议和红军长征的胜利》·共产党员网","url":"https://fuwu.12371.cn/2016/07/22/ARTI1469154834425831.shtml"},{"id":"xiangjiang_lines","text":"1934 年 10 月下旬至 12 月初，中央红军连续突破国民党军三道封锁线；在突破第四道封锁线的湘江战役中遭受重大损失，由出发时的 8.6 万余人减至 3 万余人。","source":"《中国共产党一百年大事记》·共产党员网","url":"https://www.12371.cn/2021/06/28/ARTI1624828749818652.shtml?cid=5100"}]},{"id":"tongdao","name":"通道","date":"1934.12","title":"通道转兵，西进贵州","text":"1934 年 12 月 12 日，中革军委在湖南通道召开紧急会议，讨论中央红军的行动方向。会后中革军委发出“万万火急”电令，部署“我军明十三号继续西进”，中央红军改向贵州方向前进。","source":"《通道会议：中央红军首次实现“转兵”》·中央党史和文献研究院","url":"https://www.dswxyjy.org.cn/n1/2026/0918/c244516-40801324.html","x":63,"y":62,"questions":["通道会议是什么时候召开的？","通道转兵后红军往哪里走？"],"extra":[{"id":"tongdao_liming","text":"1934 年 12 月 18 日，中共中央在贵州黎平召开政治局会议，通过《政治局关于战略方针之决定》，否定在湘西创建根据地的原计划，确定以遵义为中心的川黔边新根据地。","source":"《黎平会议：“伟大转折的起点”》·中央党史和文献研究院","url":"https://www.dswxyjy.org.cn/n1/2026/1009/c244516-40811392.html"},{"id":"tongdao_houchang","text":"1934 年 12 月 31 日晚至 1935 年 1 月 1 日凌晨，中共中央在乌江南岸瓮安县猴场召开政治局会议，再次否定回头东进湘西的主张，决定立即强渡乌江、攻占遵义。","source":"《猴场会议：伟大转折的前夜》·人民网","url":"https://cpc.people.com.cn/n1/2025/0111/c443712-40399843.html"}]},{"id":"zunyi","name":"遵义","date":"1935.01","title":"遵义会议，重要转折","text":"1935 年 1 月 15 日至 17 日，中共中央在贵州遵义召开政治局扩大会议，集中解决当时具有决定意义的军事和组织问题，是中国共产党历史上生死攸关的转折点。","source":"《中国共产党一百年大事记》·共产党员网","url":"https://www.12371.cn/2021/06/28/ARTI1624828749818652.shtml?cid=5100","x":53,"y":68,"questions":["遵义会议什么时候召开？","遵义会议为什么重要？"],"extra":[{"id":"zunyi_detail","text":"遵义会议批评第五次反“围剿”和长征以来军事领导上的错误，改组中央领导机构，选举毛泽东为中央政治局常委。会议是中国共产党独立自主解决路线、方针和政策的重要会议，在危急时刻挽救了党和红军。","source":"《党史百年·天天读：1月15日》·共产党员网","url":"https://www.12371.cn/2021/01/13/ARTI1610503077031871.shtml"},{"id":"zunyi_wujiang","text":"1935 年 1 月 1 日至 6 日，中央红军在江界河、回龙场、茶山关等渡口强渡乌江。","source":"《乌江：红军在这里开始反攻》·人民网","url":"http://politics.people.com.cn/n1/2019/0711/c1001-31227400.html"},{"id":"zunyi_occupy","text":"1935 年 1 月 7 日，中央红军占领黔北重镇遵义。","source":"《猴场会议：伟大转折的前夜》·人民网","url":"https://cpc.people.com.cn/n1/2025/0111/c443712-40399843.html"},{"id":"zunyi_loushan","text":"1935 年 2 月 18 日至 21 日，红军二渡赤水回师黔北；25 日进攻娄山关，经反复争夺夺关，随后再占遵义。这是长征以来第一个大胜仗。","source":"《娄山关，而今迈步从头越》·人民网","url":"http://politics.people.com.cn/n1/2019/0712/c1001-31229130.html"}]},{"id":"chishui","name":"赤水河","date":"1935.01—03","title":"四渡赤水","text":"1935 年 1 月下旬至 3 月，中央红军在川黔滇边境地区四渡赤水河，机动周旋。","source":"《中国共产党一百年大事记》·共产党员网","url":"https://www.12371.cn/2021/06/28/ARTI1624828749818652.shtml?cid=5100","x":42,"y":59,"questions":["四渡赤水发生在什么时期？","第一次和第四次渡河分别是什么时候？"],"extra":[{"id":"chishui_detail","text":"1935 年 1 月 29 日，红军首次渡过赤水河；2 月 18 日至 21 日二渡；3 月 16 日至 17 日三渡；3 月 21 日至 22 日四渡。","source":"《党史百年·天天读：1月19日》·共产党员网","url":"https://www.12371.cn/2021/01/17/ARTI1610856841161387.shtml"}]},{"id":"jinsha","name":"金沙江","date":"1935.05","title":"巧渡金沙江","text":"1935 年 5 月上旬，中央红军渡过金沙江，摆脱敌军的围追堵截，继续北上。","source":"《红军长征巧渡金沙江，“巧”在哪里？》·共产党员网","url":"https://www.12371.cn/2023/08/20/ARTI1692495372136387.shtml","x":28,"y":73,"questions":["中央红军什么时候渡过金沙江？","巧渡金沙江有哪些策略？"],"extra":[{"id":"jinsha_detail","text":"1935 年 4 月，中央红军佯攻昆明，调动敌军，创造北渡金沙江的条件。先遣部队于 5 月 3 日抵达皎平渡，为主力渡江打前站。","source":"《七只船 三万人》·共产党员网","url":"https://news.12371.cn/2016/10/13/ARTI1476351910026867.shtml"}]},{"id":"luding","name":"泸定桥","date":"1935.05","title":"飞夺泸定桥","text":"1935 年 5 月 29 日，中央红军部队夺取大渡河上的泸定桥，为继续北上打开通路。","source":"《将精神的种子埋入时间》·共产党员网","url":"https://news.12371.cn/2016/10/19/ARTI1476825092629521.shtml","x":16,"y":51,"questions":["飞夺泸定桥发生在什么时候？","夺取泸定桥有什么作用？"],"extra":[{"id":"luding_detail","text":"1935 年 5 月 29 日，中央红军左纵队先头部队从泸定桥西头发起夺桥战斗，抢占大桥。","source":"《党史百年·天天读：5月29日》·共产党员网","url":"https://www.12371.cn/2021/05/27/ARTI1622097439084125.shtml"},{"id":"luding_dadu","text":"1935 年 5 月 24 日夜，中央红军先头部队袭占安顺场渡口；25 日晨，红一团一营营长孙继先挑选 17 名勇士乘木船强渡大渡河，控制北岸渡口。因船只不足、无法架桥，主力继续北上夺取泸定桥。","source":"《凭借这艘翘首木船，红军战士渡过不可逾越的天险》·共产党员网","url":"https://www.12371.cn/2021/11/10/ARTI1636516276417977.shtml"}]},{"id":"jiajin","name":"夹金山","date":"1935.06","title":"翻越第一座大雪山","text":"1935 年 6 月，中央红军翻越长征途中第一座大雪山夹金山（海拔 4000 余米）。6 月 12 日先头部队翻越，6 月 18 日中央红军所有部队全部翻越夹金山。","source":"《历史记忆中的长征》第八集“红军翻越大雪山”·共产党员网","url":"https://xuexi.12371.cn/2016/12/16/ARTI1481871917232610.shtml","x":23,"y":38,"questions":["红军什么时候翻越夹金山？","夹金山为什么难翻？"],"extra":[{"id":"jiajin_maogong","text":"1935 年 6 月 12 日，中央红军一部与红四方面军一部在达维镇会师；6 月 18 日，中共中央和中央红军主力到达懋功（今四川小金）地区。","source":"《红一、红四方面军懋功会师》·中央党史和文献研究院","url":"https://www.dswxyjy.org.cn/n/2013/1106/c244520-23443430.html"},{"id":"jiajin_lianghekou","text":"1935 年 6 月 26 日，中共中央政治局在懋功以北的两河口召开会议，确定集中主力北上、创造川陕甘根据地的战略方针；6 月 28 日通过《关于一、四方面军会合后战略方针的决定》。","source":"《党史百年·天天读：6月26日》·共产党员网","url":"https://www.12371.cn/2021/06/23/ARTI1624428511719801.shtml"}]},{"id":"caodi","name":"草地","date":"1935.08","title":"穿越松潘草地","text":"1935 年 8 月 21 日，右路军从毛儿盖出发，穿越川西北松潘草地，8 月 27 日到达班佑；左路军由卓克基、马塘出发向阿坝开进。草地泥沼遍布、粮盐断绝，红军付出巨大牺牲。","source":"《1935年8月21日 红军长征过草地》·人民网","url":"http://m.people.cn/n4/0/2017/0821/c2771-9732578_4.html","x":35,"y":31,"questions":["红军什么时候过草地？","过草地为什么损失很大？"],"extra":[{"id":"caodi_shawo","text":"1935 年 8 月 4 日至 6 日，中共中央政治局在毛儿盖以南的沙窝召开会议，重申北上创造川陕甘根据地的方针。","source":"《长征中的会议·沙窝会议》·共产党员网","url":"https://fuwu.12371.cn/2012/06/11/ARTI1339400564382590_9.shtml"},{"id":"caodi_maogai","text":"1935 年 8 月 20 日，中共中央政治局在毛儿盖召开会议，通过《关于目前战略方针之补充决定》，确定以岷州、洮河为中心向东发展。","source":"《长征中的会议·毛儿盖会议》·共产党员网","url":"https://fuwu.12371.cn/2012/06/11/ARTI1339400564382590_10.shtml"}]},{"id":"lazikou","name":"腊子口","date":"1935.09","title":"突破天险腊子口","text":"1935 年 9 月 16 日，红一方面军到达甘肃迭部腊子口；红一军团第二师第四团采取正面进攻与侧翼攀崖迂回相结合，至 17 日凌晨突破鲁大昌部两道防线，夺取天险腊子口，打开北上甘南的通道。","source":"《天险腊子口战役遗址（甘肃篇）》·中央党史和文献研究院","url":"https://www.dswxyjy.org.cn/n/2013/0407/c222137-21044764.html","x":40,"y":14,"questions":["腊子口战斗发生在什么时候？","腊子口为什么重要？"],"extra":[{"id":"lazikou_hadapu","text":"1935 年 9 月 18 日，中央红军到达甘肃哈达铺；毛泽东从国民党《大公报》上得知陕北有根据地和红军，随后在 9 月 22 日的团以上干部会议上确定到陕北建立根据地。","source":"《百年瞬间：中央红军长征来到哈达铺》·共产党员网","url":"https://www.12371.cn/2021/02/22/VIDE1613964001034993.shtml"},{"id":"lazikou_shaan","text":"1935 年 9 月 22 日，红一方面军在哈达铺改称中国工农红军陕甘支队，下辖 3 个纵队。","source":"《长征“奠基礼”，毛主席题词：“英勇胜利”》·新华网","url":"https://www.news.cn/mil/2016-08/14/c_129228090.htm"},{"id":"lazikou_bangluo","text":"1935 年 9 月 27 日，陕甘支队占领通渭榜罗镇；当天中央政治局常委开会，决定把长征落脚点放在陕北，提出保卫与扩大陕北苏区的新方针。","source":"《长征中的会议·榜罗镇会议》·共产党员网","url":"https://fuwu.12371.cn/2012/06/11/ARTI1339400564382590_13.shtml"}]},{"id":"wuqi","name":"吴起镇","date":"1935.10","title":"抵达陕北","text":"1935 年 10 月 19 日，中共中央率红军陕甘支队到达陕北吴起镇，中央红军主力长征胜利结束。","source":"《中国共产党一百年大事记》·共产党员网","url":"https://www.12371.cn/2021/06/28/ARTI1624828749818652.shtml?cid=5100","x":70,"y":20,"questions":["陕甘支队什么时候到达吴起镇？","到达吴起镇有什么意义？"],"extra":[{"id":"wuqi_red25","text":"1934 年 11 月 16 日，红二十五军从河南罗山何家冲出发开始长征，历时 10 个月转战 9000 里，1935 年 9 月率先到达陕北，是长征中最先到达陕北的红军部队。","source":"《长征中，这支红军队伍人数不减反增》·共产党员网","url":"https://www.12371.cn/2022/01/04/ARTI1641253471375521.shtml"},{"id":"wuqi_yongping","text":"1935 年 9 月 15 日，红二十五军到达陕西延川永坪镇；次日与红二十六、二十七军会师；17 日联席会议决定组成红十五军团。","source":"《巧布“口袋阵” 劳山开新局》·人民网","url":"https://cpc.people.com.cn/n1/2026/0802/c443712-40772338.html"}]},{"id":"zhiluozhen","name":"直罗镇","date":"1935.11","title":"直罗镇战役，奠基西北","text":"1935 年 11 月，红一方面军在陕西鄜县（今富县）直罗镇地区设伏，歼灭东北军一个师又一个团，巩固了陕甘革命根据地。","source":"《直罗镇战役（长征·光辉历程）》·人民网","url":"http://military.people.com.cn/n1/2016/1026/c1011-28807397.html","x":82,"y":31,"questions":["直罗镇战役发生在什么时候？","为什么说直罗镇战役是“奠基礼”？"],"extra":[{"id":"zhiluozhen_dianji","text":"1935 年 11 月 30 日，毛泽东在报告中指出，直罗镇战役的胜利“算是举行了奠基礼”。","source":"《党史百年·天天读：11月30日》·共产党员网","url":"https://www.12371.cn/2021/11/25/ARTI1637806871060964.shtml"}]},{"id":"huining","name":"会宁","date":"1936.10.09","title":"红一、红四方面军会师","text":"1936 年 10 月 9 日，红四方面军在甘肃会宁与红一方面军会师。","source":"《多视角下看长征》·共产党员网","url":"https://www.12371.cn/2021/10/19/ARTI1634643519286309.shtml","x":50,"y":27,"questions":["哪些部队在会宁会师？","会宁会师发生在什么时候？"],"extra":[{"id":"huining_red4","text":"1935 年 3 月 28 日夜，红四方面军从塔山湾等渡口强渡嘉陵江，撤离川陕苏区西进，开始长征。","source":"《红四方面军铸就历史铁流与英雄战歌》·人民网","url":"http://dangshi.people.com.cn/n1/2019/0223/c85037-30898568-3.html"}]},{"id":"jiangtaibao","name":"将台堡","date":"1936.10.22","title":"红一、红二方面军会师","text":"1936 年 10 月 22 日，红二方面军在将台堡（今属宁夏西吉）与红一方面军会师。三大主力先后会师，标志着红军长征胜利结束。","source":"《多视角下看长征》·共产党员网","url":"https://www.12371.cn/2021/10/19/ARTI1634643519286309.shtml","x":57,"y":11,"questions":["哪些部队在将台堡会师？","将台堡会师有什么意义？"],"extra":[{"id":"jiangtaibao_red2start","text":"1935 年 11 月 19 日傍晚，红二、红六军团主力 1.7 万余人从湖南桑植县刘家坪、轿子垭地区出发，开始长征。","source":"《百年瞬间：中国工农红军红二、六军团开始长征》·共产党员网","url":"https://www.12371.cn/2021/11/19/VIDE1637314320431426.shtml"},{"id":"jiangtaibao_red2route","text":"1936 年 7 月，红二、红六军团与红四方面军在甘孜会师；红二、红六军团和红三十二军合编为红二方面军；10 月 22 日，红二方面军在将台堡与红一方面军会师。","source":"《关于红军时期部队番号的演变》·共产党员网","url":"https://www.12371.cn/2023/01/06/ARTI1672991184454845.shtml"}]}];
const json = (value, status = 200) => Response.json(value, {status, headers:{'cache-control':'no-store','x-content-type-options':'nosniff'}});
